import { describe, expect, it } from 'vitest';
import { parseBoardCode, SIZES } from './boardCode.ts';
import { drawBounded, nextRandom } from './deck.ts';
import { createGame } from './state.ts';

const EXAMPLE_DECK = [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3];

describe('version 1 board generation', () => {
  it('matches the published Park-Miller states', () => {
    let state = 1;
    const states: number[] = [];
    for (let index = 0; index < 5; index += 1) {
      state = nextRandom(state);
      states.push(state);
    }
    expect(states).toEqual([16807, 282475249, 1622650073, 984943658, 1144108930]);
  });

  it('rejects the biased upper tail before returning a bounded draw', () => {
    // 739806647 is the modular inverse seed whose first draw is 2147483646.
    expect(drawBounded(739806647, 100)).toEqual({ state: 2147466840, value: 39 });
  });

  it('matches independent literal deal vectors', () => {
    expect(createGame('np1-4-1')?.deck).toEqual(EXAMPLE_DECK);
    // This second literal was calculated independently with Python integer arithmetic.
    expect(createGame('np1-4-2147483646')?.deck).toEqual(
      [6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3],
    );
  });

  it.each(SIZES)('deals exactly two of every face on a %ix%i board', (size) => {
    const game = createGame(`np1-${size}-17`);
    expect(game).not.toBeNull();
    const deck = game?.deck ?? [];
    expect(deck).toHaveLength(size * size);
    const counts = new Map<number, number>();
    for (const face of deck) counts.set(face, (counts.get(face) ?? 0) + 1);
    expect(counts.size).toBe(size * size / 2);
    expect([...counts.values()].every((count) => count === 2)).toBe(true);
    expect(Object.isFrozen(game?.board)).toBe(true);
    expect(Object.isFrozen(deck)).toBe(true);
  });

  it.each(['np1-4-0', 'np1-4-01', 'np1-04-1', 'np1-5-1', 'np2-4-1',
    'np1-4-2147483647', 'np1-4-1.0', 'np1-4-+1', 'np1-4-1\n', ' np1-4-1',
    'np1-4-1 ', 'np1-4-9007199254740993', 'np1-4-1e2'])('rejects %j', (code) => {
    expect(parseBoardCode(code)).toBeNull();
    expect(createGame(code)).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { SIZES } from './boardCode.ts';
import { formatTime } from './formatTime.ts';
import { createGame, isWon } from './state.ts';
import type { GameState } from './state.ts';
import { activateCard, advanceGame, ELAPSED_CAP, MOVE_CAP } from './transitions.ts';

function initial(code = 'np1-4-1'): GameState {
  const game = createGame(code);
  if (!game) throw new Error('Invalid test board');
  return game;
}

function turn(game: GameState, first: number, second: number): GameState {
  return activateCard(activateCard(game, first), second);
}

describe('turn transitions', () => {
  it('starts on the first valid reveal and ignores repeated or invalid activation', () => {
    const game = initial();
    expect(advanceGame(game, 5000)).toBe(game);
    expect(activateCard(game, -1)).toBe(game);
    expect(activateCard(game, 16)).toBe(game);
    expect(activateCard(game, 1.5)).toBe(game);
    const revealed = activateCard(game, 0);
    expect(revealed).toMatchObject({ started: true, moves: 0, selection: { kind: 'one', index: 0 } });
    expect(activateCard(revealed, 0)).toBe(revealed);
    expect(game).toMatchObject({ started: false, selection: { kind: 'closed' } });
  });

  it('matches immediately, counts one move, and ignores matched cards', () => {
    const matched = turn(initial(), 0, 11);
    expect(matched).toMatchObject({ matched: [0, 11], moves: 1, selection: { kind: 'closed' } });
    expect(activateCard(matched, 11)).toBe(matched);
    const selected = activateCard(matched, 1);
    expect(activateCard(selected, 0)).toBe(selected);
  });

  it('ignores activation during a mismatch and closes both at exactly 800 active ms', () => {
    const mismatch = turn(initial(), 0, 1);
    expect(mismatch).toMatchObject({ moves: 1, selection: { kind: 'mismatch', remainingMs: 800 } });
    expect(activateCard(mismatch, 2)).toBe(mismatch);
    const waiting = advanceGame(mismatch, 799);
    expect(waiting.selection).toMatchObject({ kind: 'mismatch', remainingMs: 1 });
    expect(advanceGame(waiting, 1)).toMatchObject({ elapsedMs: 800, selection: { kind: 'closed' } });
    expect(activateCard(advanceGame(waiting, 1), 2).selection).toEqual({ kind: 'one', index: 2 });
  });

  it('preserves fractional active time independently of render frequency', () => {
    const game = turn(initial(), 0, 1);
    const stepped = advanceGame(advanceGame(game, 300.25), 499.75);
    expect(stepped).toEqual(advanceGame(game, 800));
    expect(advanceGame(game, 799.75).selection).toMatchObject({ remainingMs: 0.25 });
  });

  it('continues turns and mismatch timing after move and elapsed caps', () => {
    const game = { ...initial(), moves: MOVE_CAP, elapsedMs: ELAPSED_CAP, started: true };
    const mismatch = turn(game, 0, 1);
    expect(mismatch.moves).toBe(MOVE_CAP);
    const closed = advanceGame(mismatch, 800);
    expect(closed.selection).toEqual({ kind: 'closed' });
    expect(closed.elapsedMs).toBe(ELAPSED_CAP);
    expect(turn(closed, 0, 11).matched).toEqual([0, 11]);
  });

  it.each(SIZES)('completes every pair on a side-%i board', (size) => {
    let state = initial(`np1-${size}-1`);
    for (let face = 0; face < state.deck.length / 2; face += 1) {
      const positions = state.deck.flatMap((value, index) => value === face ? [index] : []);
      const first = positions[0];
      const second = positions[1];
      if (first === undefined || second === undefined) throw new Error('Missing pair');
      state = advanceGame(activateCard(state, first), 10);
      state = activateCard(state, second);
    }
    expect(isWon(state)).toBe(true);
    expect(state.moves).toBe(size * size / 2);
    expect(state.selection).toEqual({ kind: 'closed' });
    expect(advanceGame(state, 10_000)).toBe(state);
    expect(activateCard(state, 0)).toBe(state);
  });

  it('ignores invalid time and formats seconds without wrapping minutes', () => {
    const game = activateCard(initial(), 0);
    for (const time of [0, -1, NaN, Infinity]) expect(advanceGame(game, time)).toBe(game);
    expect(formatTime(999)).toBe('0:00');
    expect(formatTime(61_999)).toBe('1:01');
    expect(formatTime(3_600_000)).toBe('60:00');
    expect(formatTime(ELAPSED_CAP)).toBe('5999:59');
  });
});
import { describe, expect, it } from 'vitest';
import { createGame } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import { decodeSnapshot, encodeSnapshot, SNAPSHOT_BYTE_LIMIT } from './snapshot.ts';
import { parseLimitedJson } from './formatValidation.ts';

const BASE = { version: 1, boardCode: 'np1-4-1', matched: [0, 11],
  selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 },
  moves: 2, elapsedMs: 1500, started: true };
const snapshot = (changes: Record<string, unknown> = {}): string => JSON.stringify({ ...BASE, ...changes });

describe('version 1 snapshots', () => {
  it('round-trips the documented example without adding derived fields', () => {
    const state = decodeSnapshot(snapshot());
    expect(state).not.toBeNull();
    if (!state) throw new Error('Example must parse');
    expect(JSON.parse(encodeSnapshot(state))).toEqual(BASE);
    expect(state.deck).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
  });

  it('round-trips a new game, single reveal, match and completed game', () => {
    const game = createGame('np1-4-1');
    if (!game) throw new Error('Invalid test board');
    const reveal = activateCard(game, 0);
    const matched = activateCard(reveal, 11);
    for (const state of [game, reveal, matched]) expect(decodeSnapshot(encodeSnapshot(state))).toEqual(state);
    const completed = decodeSnapshot(snapshot({ matched: Array.from({ length: 16 }, (_, i) => i),
      selection: { kind: 'closed' }, moves: 8 }));
    expect(completed?.matched).toHaveLength(16);
  });

  it('exports whole milliseconds without dropping a pending mismatch', () => {
    const state = decodeSnapshot(snapshot());
    if (!state) throw new Error('Invalid test snapshot');
    const precise = advanceGame(state, 299.75);
    expect(JSON.parse(encodeSnapshot(precise))).toMatchObject({ elapsedMs: 1799,
      selection: { remainingMs: 1 } });
    expect(decodeSnapshot(encodeSnapshot(precise))).not.toBeNull();
  });

  it.each([
    { version: 2 }, { unexpected: true }, { deck: [] }, { boardCode: ' np1-4-1' },
    { boardCode: 'np1-4-1\n' }, { matched: [0] }, { matched: [0, 1] },
    { matched: [0, 11, 11] }, { matched: [0, 16] }, { matched: [-1, 11] },
    { matched: ['0', 11] }, { matched: null }, { started: 1 }, { started: false },
    { moves: 1 }, { moves: -1 }, { moves: 2.5 }, { moves: 1_000_000 },
    { moves: Number.MAX_SAFE_INTEGER + 1 }, { elapsedMs: -1 }, { elapsedMs: 1.5 },
    { elapsedMs: 360_000_000 }, { elapsedMs: null },
    { selection: { kind: 'closed', index: 2 } },
    { selection: { kind: 'one', index: 0 } },
    { selection: { kind: 'one', index: 16 } },
    { selection: { kind: 'one', index: 1, remainingMs: 10 } },
    { selection: { kind: 'mismatch', first: 1, second: 1, remainingMs: 300 } },
    { selection: { kind: 'mismatch', first: 1, second: 9, remainingMs: 300 } },
    { selection: { kind: 'mismatch', first: 0, second: 2, remainingMs: 300 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 0 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 801 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 1.5 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 1, extra: true } },
    { selection: { kind: 'unknown' } }, { selection: null },
  ])('rejects inconsistent or extended state %j', (changes) => {
    expect(decodeSnapshot(snapshot(changes))).toBeNull();
  });

  it('requires pristine unstarted state and one reveal for started zero-move state', () => {
    const pristine = { matched: [], selection: { kind: 'closed' }, moves: 0,
      elapsedMs: 0, started: false };
    expect(decodeSnapshot(snapshot(pristine))).not.toBeNull();
    expect(decodeSnapshot(snapshot({ ...pristine, elapsedMs: 1 }))).toBeNull();
    expect(decodeSnapshot(snapshot({ ...pristine, selection: { kind: 'one', index: 1 } }))).toBeNull();
    expect(decodeSnapshot(snapshot({ ...pristine, started: true }))).toBeNull();
    expect(decodeSnapshot(snapshot({ ...pristine, started: true, selection: { kind: 'one', index: 1 } })))
      .not.toBeNull();
  });

  it('validates declared constraints without reconstructing earlier history', () => {
    expect(decodeSnapshot(snapshot({ matched: [], selection: { kind: 'closed' },
      moves: 999999, elapsedMs: 359999999 }))).not.toBeNull();
    expect(decodeSnapshot(snapshot({ matched: [], selection: { kind: 'one', index: 1 },
      moves: 0, elapsedMs: 359999999 }))).not.toBeNull();
  });

  it('rejects malformed JSON and enforces UTF-8 byte limits', () => {
    for (const text of ['null', '[]', '{}', '{', '', 'true']) expect(decodeSnapshot(text)).toBeNull();
    const valid = snapshot();
    expect(decodeSnapshot(valid.padEnd(SNAPSHOT_BYTE_LIMIT, ' '))).not.toBeNull();
    expect(decodeSnapshot(valid.padEnd(SNAPSHOT_BYTE_LIMIT + 1, ' '))).toBeNull();
    expect(parseLimitedJson('"é"', 3)).toBeNull();
    expect(parseLimitedJson('"é"', 4)).toBe('é');
  });
});
import { describe, expect, it } from 'vitest';
import { replayGame, REPLAY_ACTION_LIMIT, REPLAY_BYTE_LIMIT } from './replay.ts';
import { encodeSnapshot } from './snapshot.ts';

const BASE = { version: 1, boardCode: 'np1-4-1',
  actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 };
const replay = (changes: Record<string, unknown> = {}): string => JSON.stringify({ ...BASE, ...changes });

describe('version 1 replay', () => {
  it('replays the published example', () => {
    const state = replayGame(replay());
    expect(state).toMatchObject({ matched: [0, 11], moves: 1, elapsedMs: 800,
      started: true, selection: { kind: 'closed' } });
    if (!state) throw new Error('Example must parse');
    expect(JSON.parse(encodeSnapshot(state))).toEqual({ version: 1, boardCode: 'np1-4-1',
      matched: [0, 11], moves: 1, elapsedMs: 800, started: true, selection: { kind: 'closed' } });
  });

  it('resolves a mismatch before an equal-time action and keeps equal-time array order', () => {
    const state = replayGame(replay({ actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 },
      { atMs: 799, index: 2 }, { atMs: 800, index: 2 }, { atMs: 800, index: 6 }], endMs: 800 }));
    expect(state).toMatchObject({ matched: [2, 6], moves: 2, elapsedMs: 800,
      selection: { kind: 'closed' } });
  });

  it('starts the clock at the first reveal, not the replay origin', () => {
    expect(replayGame(replay({ actions: [{ atMs: 3000, index: 0 }], endMs: 3500 })))
      .toMatchObject({ elapsedMs: 500, moves: 0 });
    expect(replayGame(replay({ actions: [], endMs: 10000 })))
      .toMatchObject({ elapsedMs: 0, started: false });
  });

  it('applies ignored activations and leaves unfinished mismatches pending', () => {
    const state = replayGame(replay({ actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 0 },
      { atMs: 100, index: 1 }, { atMs: 200, index: 2 }], endMs: 400 }));
    expect(state).toMatchObject({ moves: 1, elapsedMs: 400,
      selection: { kind: 'mismatch', first: 0, second: 1, remainingMs: 500 } });
  });

  it('caps the elapsed clock while accepting safe-integer replay timeline times', () => {
    expect(replayGame(replay({ endMs: Number.MAX_SAFE_INTEGER })))
      .toMatchObject({ elapsedMs: 359999999 });
    expect(replayGame(replay({ actions: [{ atMs: Number.MAX_SAFE_INTEGER - 1, index: 0 }],
      endMs: Number.MAX_SAFE_INTEGER })))
      .toMatchObject({ elapsedMs: 1 });
  });

  it('stops time at victory even if later actions or end time occur', () => {
    const pairs = [[2, 6], [10, 14], [4, 5], [8, 15], [12, 13], [3, 7], [0, 11], [1, 9]];
    const actions = pairs.flatMap((pair, index) => pair.map((position) => ({ atMs: index * 100, index: position })));
    expect(replayGame(replay({ actions: [...actions, { atMs: 10000, index: 0 }], endMs: 20000 })))
      .toMatchObject({ moves: 8, elapsedMs: 700, matched: pairs.flat() });
  });

  it.each([
    { version: 2 }, { extra: true }, { boardCode: 'np1-4-1\n' }, { actions: null },
    { actions: [{ atMs: 0, index: 0, extra: true }] },
    { actions: [{ atMs: -1, index: 0 }] }, { actions: [{ atMs: 0.5, index: 0 }] },
    { actions: [{ atMs: 0, index: 16 }] }, { actions: [{ atMs: 0, index: -1 }] },
    { actions: [{ atMs: 0, index: 1.5 }] }, { actions: [{ index: 0 }] },
    { actions: [{ atMs: 1, index: 0 }, { atMs: 0, index: 1 }] },
    { actions: [{ atMs: 801, index: 0 }] }, { endMs: -1 }, { endMs: 1.5 },
    { endMs: Number.MAX_SAFE_INTEGER + 1 }, { endMs: null },
  ])('rejects invalid replay %j', (changes) => expect(replayGame(replay(changes))).toBeNull());

  it('enforces complete JSON shape, byte and action limits', () => {
    for (const text of ['null', '{}', '[]', '{', '']) expect(replayGame(text)).toBeNull();
    const maxActions = Array.from({ length: REPLAY_ACTION_LIMIT }, () => ({ atMs: 0, index: 0 }));
    expect(replayGame(replay({ actions: maxActions }))).not.toBeNull();
    expect(replayGame(replay({ actions: [...maxActions, { atMs: 0, index: 0 }] }))).toBeNull();
    expect(replayGame(replay().padEnd(REPLAY_BYTE_LIMIT, ' '))).not.toBeNull();
    expect(replayGame(replay().padEnd(REPLAY_BYTE_LIMIT + 1, ' '))).toBeNull();
  });
});

