import { defineConfig } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  workers: 2,
  timeout: 60_000,
  expect: { timeout: 5_000 },
  reporter: [['list']],
  use: { browserName: 'chromium', baseURL: 'http://127.0.0.1:4173',
    viewport: { width: 1280, height: 800 }, trace: 'retain-on-failure' },
  webServer: { command: 'npm exec vite preview -- --host 127.0.0.1 --port 4173 --strictPort',
    url: 'http://127.0.0.1:4173', reuseExistingServer: false },
});
import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { createGame } from '../src/game/state.ts';
import { decodeSnapshot } from '../src/game/snapshot.ts';

export const CODE = 'np1-4-1';
export const PAIRS = [[0, 11], [1, 9], [2, 6], [3, 7], [4, 5], [8, 15], [10, 14], [12, 13]];

export async function start(page: Page, frozen = false): Promise<void> {
  if (frozen) {
    const time = new Date('2026-11-04T12:00:00Z');
    await page.clock.install({ time });
    await page.clock.pauseAt(new Date(time.getTime() + 1000));
  }
  await page.goto('/');
  await expect(page.locator('.card')).toHaveCount(16);
}

export async function reproduce(page: Page): Promise<void> {
  const details = page.locator('details');
  if (await details.getAttribute('open') === null) await page.getByText('Reproduce a game', { exact: true }).click();
}

export async function loadBoard(page: Page, code = CODE): Promise<void> {
  await reproduce(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click({ force: true });
}

export async function reveal(page: Page, index: number): Promise<void> {
  await page.locator('.card').nth(index).dispatchEvent('click', { button: 0, detail: 1 });
}

export async function exported(page: Page) {
  await reproduce(page);
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click({ force: true });
  const text = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const state = decodeSnapshot(text);
  if (!state) throw new Error('Export must be a valid snapshot');
  return state;
}

export function snapshot(changes: Record<string, unknown> = {}): string {
  return JSON.stringify({ version: 1, boardCode: CODE, matched: [], selection: { kind: 'closed' },
    moves: 0, elapsedMs: 0, started: false, ...changes });
}

export async function loadSnapshot(page: Page, text: string): Promise<void> {
  await reproduce(page);
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(text);
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click({ force: true });
}

export async function solve(page: Page, code = CODE): Promise<void> {
  const game = createGame(code);
  if (!game) throw new Error('Invalid test board');
  for (let face = 0; face < game.deck.length / 2; face += 1) {
    const first = game.deck.indexOf(face);
    const second = game.deck.lastIndexOf(face);
    await reveal(page, first);
    await reveal(page, second);
  }
}
import { expect, test } from '@playwright/test';
import { SIZES } from '../src/game/boardCode.ts';
import { exported, loadBoard, reveal, solve, start } from './helpers.ts';

for (const size of SIZES) {
  test(`completes every pair on ${size}x${size}`, async ({ page }) => {
    await start(page);
    const code = `np1-${size}-1`;
    await loadBoard(page, code);
    await solve(page, code);
    await expect(page.getByRole('heading', { name: 'All pairs found!' })).toBeVisible();
    await expect(page.locator('.card.matched')).toHaveCount(size * size);
    await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
  });
}

test('starts on first reveal, ignores repeats and closes a miss at exactly 800 active ms', async ({ page }) => {
  await start(page, true);
  await loadBoard(page);
  await page.clock.runFor(5000);
  expect((await exported(page)).elapsedMs).toBe(0);
  await reveal(page, 0);
  await reveal(page, 0);
  expect((await exported(page)).moves).toBe(0);
  await reveal(page, 11);
  await expect(page.locator('.card.matched')).toHaveCount(2);
  await reveal(page, 1);
  await reveal(page, 2);
  await reveal(page, 3);
  await page.clock.runFor(799);
  expect((await exported(page)).selection).toEqual({ kind: 'mismatch', first: 1, second: 2, remainingMs: 1 });
  await page.clock.runFor(1);
  const state = await exported(page);
  expect(state.selection).toEqual({ kind: 'closed' });
  expect(state.moves).toBe(2);
  expect(state.elapsedMs).toBe(800);
  await reveal(page, 2);
  await expect(page.locator('.card').nth(2)).toHaveAccessibleName(/cyan solid circle.*revealed/);
});

test('victory stops the clock and its single pulse ends after 600 ms', async ({ page }) => {
  await start(page, true);
  await loadBoard(page);
  await reveal(page, 0);
  await page.clock.runFor(1250);
  await reveal(page, 11);
